#include "tigersheets/main_window.hpp"
#include "tigersheets/grid.hpp"
#include <QApplication>
#include <QAbstractItemDelegate>
#include <QFontMetricsF>
#include <QStyleOptionViewItem>
#include <QTableView>
#include <QTemporaryDir>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool v,const char* message){if(!v)throw std::runtime_error(message);}
int main(int argc,char**argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{MainWindow window;window.resize(1280,720);window.show();QApplication::processEvents();auto* view=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(view->model());const auto id=model->sheetId().toStdString();require(model->apply(Json::array({{{"type","set_sheet_layout"},{"sheet",id},{"defaultStyle",{{"fontFamily","Calibri"},{"fontSize",12}}}},{{"type","set_cell"},{"sheet",id},{"row",2},{"col",2},{"input","Income Statement:"},{"style",{{"bold",true}}}},{{"type","set_cell"},{"sheet",id},{"row",2},{"col",3},{"input","43830"},{"style",{{"numberFormat","mm/dd/yyyy"}}}}})),"source-sized native cells");for(int column:{1,2}){auto index=model->index(1,column);view->setCurrentIndex(index);require(window.executeCommand("columns.autofit"),"actual native AutoFit command");QStyleOptionViewItem option;option.initFrom(view);const auto font=model->data(index,Qt::FontRole).value<QFont>();std::cout<<"column="<<column+1<<" width="<<view->columnWidth(column)<<" text="<<model->data(index).toString().toStdString()<<" font="<<font.family().toStdString()<<" point="<<font.pointSizeF()<<" glyphs="<<QFontMetricsF(font).horizontalAdvance(model->data(index).toString())<<" hint="<<view->itemDelegate()->sizeHint(option,index).width()<<'\n';}
 const int titleWidth=view->columnWidth(1),dateWidth=view->columnWidth(2);
 require(model->apply(Json::array({{{"type","set_cell"},{"sheet",id},{"row",5000},{"col",2},{"input","Net PP&E, Goodwill & Intangibles:"},{"style",{{"indent",1}}}}})),"source longest indented label below the initial viewport");view->setCurrentIndex(model->index(1,1));require(window.executeCommand("columns.autofit"),"fit all used rows including below the viewport");std::cout<<"long fitted="<<view->columnWidth(1)<<" hinted="<<QFontMetricsF(model->data(model->index(4999,1),Qt::FontRole).value<QFont>()).horizontalAdvance(model->data(model->index(4999,1)).toString())<<std::endl;require(dateWidth==83,"native AutoFit reproduces the source83px date columns at8:52");require(titleWidth==139,"native AutoFit reproduces source139px Income Statement column at8:37");const auto longIndex=model->index(4999,1);auto authoredFont=model->data(longIndex,Qt::FontRole).value<QFont>();const auto displayFont=authoredFont;authoredFont.setFamily(QString::fromStdString(model->cellStyle(longIndex.row(),longIndex.column()).value("fontFamily",std::string("Calibri"))));const QFontMetrics metrics(authoredFont);require(view->columnWidth(1)>=metrics.horizontalAdvance(model->data(longIndex).toString())+metrics.horizontalAdvance("   ")+6,"AutoFit includes indented stored labels in the authored font beyond the visible and first1000 rows");require(model->data(longIndex,Qt::FontRole).value<QFont>()==displayFont&&model->cellStyle(longIndex.row(),longIndex.column()).value("fontFamily",std::string("Calibri"))=="Calibri","authored-font AutoFit preserves the accepted display fallback and original font declaration");const auto& fittedLayout=model->workbookView().at("sheets")[0].at("columnLayout");for(const auto& column:fittedLayout)require(column.value("bestFit",false),"AutoFit records native bestFit for every fitted column");require(window.executeCommand("columns.size",{{"size",20.0}}),"manual native column width after AutoFit");for(const auto& column:model->workbookView().at("sheets")[0].at("columnLayout"))if(column.at("index")==2)require(!column.value("bestFit",false),"manual width clears the native AutoFit flag");require(window.executeCommand("undo"),"manual width is one Undo");for(const auto& column:model->workbookView().at("sheets")[0].at("columnLayout"))if(column.at("index")==2)require(column.value("bestFit",false),"Undo restores native AutoFit state");std::cout<<"Source AutoFit geometry passed\n";}catch(const std::exception& e){std::cerr<<"FAILED: "<<e.what()<<'\n';return 1;}}
